import type { HandlerResult, OrderInput } from "../types.ts";
import { validateOrder } from "../validation/order.ts";

export function createOrder(input: OrderInput): HandlerResult {
  const validation = validateOrder(input);
  if (!validation.ok) return { status: 400, body: { errors: validation.errors } };
  return { status: 201, body: { id: `ord-${input.customerId}-${input.lines.length}`, currency: input.currency ?? "USD" } };
}

import type { HandlerResult, OrderInput } from "../types.ts";
import { validateOrder } from "../validation/order.ts";

export function quoteOrder(input: OrderInput): HandlerResult {
  const validation = validateOrder(input);
  if (!validation.ok) return { status: 400, body: { errors: validation.errors } };
  const units = input.lines.reduce((sum, line) => sum + line.quantity, 0);
  return { status: 200, body: { units, currency: input.currency ?? "USD" } };
}

import type { HandlerResult, OrderInput } from "../types.ts";
import { validateOrder } from "../validation/order.ts";

export function updateOrder(id: string, input: OrderInput): HandlerResult {
  const validation = validateOrder(input);
  if (!validation.ok) return { status: 400, body: { errors: validation.errors } };
  return { status: 200, body: { id, lines: input.lines.length } };
}

import type { OrderInput } from "../types.ts";

export interface ValidationResult {
  ok: true;
}
export interface ValidationErrorResult {
  ok: false;
  errors: string[];
}
export type ValidationResultType = ValidationResult | ValidationErrorResult;

export function validateOrder(input: OrderInput): ValidationResultType {
  const errors: string[] = [];
  if (!input.customerId || input.customerId.trim() === "") errors.push("customerId is required");
  if (!Array.isArray(input.lines) || input.lines.length === 0) errors.push("at least one line is required");
  for (const [index, line] of (input.lines ?? []).entries()) {
    if (!line.sku) errors.push(`lines[${index}].sku is required`);
    if (!Number.isInteger(line.quantity) || line.quantity <= 0) errors.push(`lines[${index}].quantity must be a positive integer`);
  }
  if (input.currency !== undefined && !/^[A-Z]{3}$/.test(input.currency)) errors.push("currency must be a 3-letter code");
  if (errors.length > 0) {
    return { ok: false, errors };
  }
  return { ok: true };
}

